6: /// A Time
7: ///
8: /// Allowed formats:
9: /// * `HH:MM:SS`
10: /// * `HH:MM:SS.FFFFFF` 1 to 6 digits are allowed
11: /// * `HH:MM`
12: /// * `HH:MM:SSZ`
13: /// * `HH:MM:SS.FFFFFFZ`
14: ///
15: /// Fractions of a second are to microsecond precision, if the value contains greater
16: /// precision, an error is raised.
17: ///
18: /// # Comparison
19: ///
20: /// `Time` supports equality (`==`) and inequality (`>`, `<`, `>=`, `<=`) comparisons.
21: ///
22: /// See [Time::partial_cmp] for how this works.
23: #[derive(Debug, PartialEq, Eq, Clone)]
24: pub struct Time {
25:     /// Hour: 0 to 23
26:     pub hour: u8,
27:     /// Minute: 0 to 59
28:     pub minute: u8,
29:     /// Second: 0 to 59
30:     pub second: u8,
31:     /// microseconds: 0 to 999999
32:     pub microsecond: u32,
33:     /// timezone offset in seconds if provided, must be >-24h and <24h
34:     // This range is to match python,
35:     // Note: [Stack Overflow suggests](https://stackoverflow.com/a/8131056/949890) larger offsets can happen
36:     pub tz_offset: Option<i32>,
37: }
