77:     /// Compare two times by inequality.
78:     ///
79:     /// `Time` supports equality (`==`, `!=`) and inequality comparisons (`>`, `<`, `>=` & `<=`).
80:     ///
81:     /// # Examples
82:     ///
83:     /// ```
84:     /// use speedate::Time;
85:     ///
86:     /// let t1 = Time::parse_str("04:05:06.07").unwrap();
87:     /// let t2 = Time::parse_str("04:05:06.08").unwrap();
88:     ///
89:     /// assert!(t1 < t2);
90:     /// ```
91:     ///
92:     ///  # Comparison with Timezones
93:     ///
94:     /// When comparing two times, we want "less than" or "greater than" refer to "earlier" or "later"
95:     /// in the absolute course of time. We therefore need to be careful when comparing times with different
96:     /// timezones. (If it wasn't for timezones, we could omit all this extra logic and thinking and just compare
97:     /// struct members directly as we do with [crate::Date] and [crate::Duration]).
98:     ///
99:     /// See [crate::DateTime::partial_cmp] for more information about comparisons with timezones.
100:     ///
101:     /// ## Timezone Examples
102:     ///
103:     /// ```
104:     /// use speedate::Time;
105:     ///
106:     /// let t1 = Time::parse_str("15:00:00Z").unwrap();
107:     /// let t2 = Time::parse_str("15:00:00+01:00").unwrap();
108:     ///
109:     /// assert!(t1 > t2);
110:     ///
111:     /// let t3 = Time::parse_str("15:00:00-01:00").unwrap();
112:     /// let t4 = Time::parse_str("15:00:00+01:00").unwrap();
113:     ///
114:     /// assert!(t3 > t4);
115:     /// ```
116:     fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
117:         match (self.tz_offset, other.tz_offset) {
118:             (Some(tz_offset), Some(other_tz_offset)) => match (self.total_seconds() as i64 - tz_offset as i64)
119:                 .partial_cmp(&(other.total_seconds() as i64 - other_tz_offset as i64))
120:             {
121:                 Some(Ordering::Equal) => self.microsecond.partial_cmp(&other.microsecond),
122:                 otherwise => otherwise,
123:             },
124:             _ => match self.total_seconds().partial_cmp(&other.total_seconds()) {
125:                 Some(Ordering::Equal) => self.microsecond.partial_cmp(&other.microsecond),
126:                 otherwise => otherwise,
127:             },
128:         }
129:     }
130: }
