fn parse_time(bytes: &[u8], offset: usize) -> Result<Self, ParseError> {
    match Time::parse_bytes_offset(bytes, offset) {
        Ok(t) => {
            if t.tz_offset.is_some() {
                return Err(ParseError::ExtraCharacters);
            }
            Ok(Self {
                positive: false, // is set above
                day: 0,
                second: t.hour as u32 * 3_600 + t.minute as u32 * 60 + t.second as u32,
                microsecond: t.microsecond,
            })
        }
        Err(
            ParseError::InvalidCharTzSign
            | ParseError::InvalidCharTzHour
            | ParseError::InvalidCharTzMinute
            | ParseError::OutOfRangeTzMinute
            | ParseError::OutOfRangeTz,
        ) => Err(ParseError::ExtraCharacters),
        Err(e) => Err(e),
    }
}

